```cpp
#include <iostream>
#include <vector>
#include <set>
#include <cmath>
#include <algorithm>
using namespace std;

const int MAX = 1000;

// Sieve to generate primes up to MAX
vector<int> primes;
bool is_composite[MAX + 1];

void sieve() {
    for (int i = 2; i <= MAX; ++i) {
        if (!is_composite[i]) {
            primes.push_back(i);
            for (int j = i * i; j <= MAX; j += i) {
                is_composite[j] = true;
            }
        }
    }
}

// Distinct prime factors for each number 0..MAX
vector<vector<int>> pf(MAX + 1);

void precompute_factors() {
    for (int i = 2; i <= MAX; ++i) {
        int n = i;
        for (int p : primes) {
            if (p * p > n) break;
            if (n % p == 0) {
                pf[i].push_back(p);
                while (n % p == 0) n /= p;
            }
        }
        if (n > 1) pf[i].push_back(n);
    }
}

// Check if a small integer is prime
bool is_prime(int x) {
    if (x < 2) return false;
    if (x == 2) return true;
    if (x % 2 == 0) return false;
    for (int i = 3; i * i <= x; i += 2) {
        if (x % i == 0) return false;
    }
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    sieve();
    precompute_factors();

    int T;
    cin >> T;
    while (T--) {
        int A, B;
        cin >> A >> B;

        // Union of distinct prime factors
        set<int> union_set;
        for (int p : pf[A]) union_set.insert(p);
        for (int p : pf[B]) union_set.insert(p);

        int cnt = union_set.size();
        cout << (is_prime(cnt) ? "Yes\n" : "No\n");
    }
    return 0;
}
```

