    mat = [''] * (n + 1)
    for i in range(1, n + 1):
        mat[i] = next(it).decode()

    # compute indegree
    indeg = [0] * (n + 1)
    for i in range(1, n + 1):
        row = mat[i]
        for j in range(1, n + 1):
            if row[j - 1] == '1':
                indeg[j] += 1

    visited = [False] * (n + 1)
    order = []

    for _ in range(n):
        # find the smallest vertex with indegree 0 that is not yet placed
        u = -1
        for v in range(1, n + 1):
            if not visited[v] and indeg[v] == 0:
                u = v
                break
        # u exists because the graph is a DAG
        order.append(u)
        visited[u] = True
        row = mat[u]
        for v in range(1, n + 1):
            if row[v - 1] == '1':
                indeg[v] -= 1

    # position of each vertex in the topological order
    pos = [0] * (n + 1)
    for idx, v in enumerate(order):
        pos[v] = idx

    # count the number of edges that can be added
    cnt = 0
    for i in range(1, n + 1):
        pi = pos[i]
        row_i = mat[i]
        for j in range(1, n + 1):
            if i != j and pi < pos[j] and row_i[j - 1] == '0':
