class Solution:
    def CountWays(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Invalid cases: empty string is valid (1 way), but if non-empty with leading zero
        if n == 0:
            return 1
        if s[0] == '0':
            return 0

        # Check for two or more consecutive zeros
        for i in range(n - 1):
            if s[i] == '0' and s[i + 1] == '0':
                return 0

        # dp[i] = number of ways to decode first i characters
        dp = [0] * (n + 1)
        dp[0] = 1          # empty string
        dp[1] = 1          # first character is non-zero (already checked)

        for i in range(2, n + 1):
            # Single digit: current character is not '0'
            if s[i - 1] != '0':
                dp[i] = (dp[i] + dp[i - 1]) % MOD

            # Two digits: check if the two-digit number is between 10 and 26
            two_digit = int(s[i - 2:i])
            if 10 <= two_digit <= 26:
                dp[i] = (dp[i] + dp[i - 2]) % MOD

        return dp[n] % MOD
