        }
    }
    int L = fwd[N1][N2];          // original LCS length

    // ---------- backward LCS ----------
    vector<vector<int>> bwd(N1 + 1, vector<int>(N2 + 1, 0));
    for (int i = N1-1; i >= 0; --i) {
        for (int j = N2-1; j >= 0; --j) {
            if (S1[i] == S2[j])
                bwd[i][j] = bwd[i+1][j+1] + 1;
            else
                bwd[i][j] = max(bwd[i+1][j], bwd[i][j+1]);
        }
    }

    unordered_set<string> distinct;

    // try every insertion position
    for (int pos = 0; pos <= N1; ++pos) {
        bool valid[26] = {false};

        // check all characters of S2 that can be matched
        for (int k = 0; k < N2; ++k) {
            int val = fwd[pos][k] + 1 + bwd[pos][k+1];
