from collections import deque

def ladderLength(beginWord: str, endWord: str, wordList: list[str]) -> int:
    # Convert to set for O(1) lookups
    word_set = set(wordList)
    if endWord not in word_set:
        return 0

    # Bidirectional BFS
    forward_set = {beginWord}
    backward_set = {endWord}
    visited_forward = set()
    visited_backward = set()

    distance = 1  # start word counts
    word_len = len(beginWord)

    while forward_set and backward_set:
        # Always expand the smaller set to minimise work
        if len(forward_set) > len(backward_set):
            forward_set, backward_set = backward_set, forward_set
            visited_forward, visited_backward = visited_backward, visited_forward

        next_set = set()
        for word in forward_set:
            # Generate all possible transformations
            for i in range(word_len):
                for c in "abcdefghijklmnopqrstuvwxyz":
                    if c == word[i]:
                        continue
                    new_word = word[:i] + c + word[i+1:]
                    if new_word in word_set and new_word not in visited_forward:
                        if new_word in backward_set:
                            # Found connection -> return total length
                            return distance + 1
                        next_set.add(new_word)
        visited_forward |= forward_set
        forward_set = next_set
        distance += 1

    return 0

# Example usage:
print(ladderLength("hit", "cog", ["hot","dot","dog","lot","log","cog"]))  # 5
print(ladderLength("hit", "cog", ["hot","dot","dog","lot","log"]))        # 0
```

