```cpp
#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <cstring>

using namespace std;
using ll = long long;

const int ALPH = 26;

struct State {
    int len, link;
    int next[ALPH];
    int occ; // occurrence count of the substrings of this state
};

class SAM {
public:
    vector<State> st;
    int last;

    SAM() {
        st.reserve(2 * 100000);
        st.push_back({0, -1, {}, 0});
        fill(st[0].next, st[0].next + ALPH, -1);
        last = 0;
    }

    void extend(char ch) {
        int c = ch - 'a';
        int cur = (int)st.size();
        st.push_back({st[last].len + 1, -1, {}, 1}); // new prefix occurrence
        fill(st[cur].next, st[cur].next + ALPH, -1);
        int p = last;
        while (p != -1 && st[p].next[c] == -1) {
            st[p].next[c] = cur;
            p = st[p].link;
        }
        if (p == -1) {
            st[cur].link = 0;
        } else {
            int q = st[p].next[c];
            if (st[p].len + 1 == st[q].len) {
                st[cur].link = q;
            } else {
                int clone = (int)st.size();
                st.push_back({st[p].len + 1, st[q].link, {}, 0}); // clone gets 0 occ
                copy(st[q].next, st[q].next + ALPH, st[clone].next);
                while (p != -1 && st[p].next[c] == q) {
                    st[p].next[c] = clone;
                    p = st[p].link;
                }
                st[q].link = st[cur].link = clone;
            }
        }
        last = cur;
    }

    int size() const { return (int)st.size(); }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;
    int n = (int)s.size();

    SAM sam;
    for (char ch : s) {
        sam.extend(ch);
    }

    int sz = sam.size();
    vector<int> occ(sz, 0);
    for (int i = 0; i < sz; ++i) occ[i] = sam.st[i].occ;

    // Topological order by length (counting sort)
    int max_len = 0;
    for (int i = 0; i < sz; ++i) {
        if (sam.st[i].len > max_len) max_len = sam.st[i].len;
    }
    vector<int> cnt_len(max_len + 1, 0);
    for (int i = 0; i < sz; ++i) {
        cnt_len[sam.st[i].len]++;
    }
    for (int i = 1; i <= max_len; ++i) {
        cnt_len[i] += cnt_len[i - 1];
    }
    vector<int> order(sz);
    for (int i = 0; i < sz; ++i) {
        order[--cnt_len[sam.st[i].len]] = i;
    }
    // Propagate occurrences from long to short
    for (int i = sz - 1; i > 0; --i) {
        int v = order[i];
        int p = sam.st[v].link;
        if (p != -1) {
            occ[p] += occ[v];
        }
    }

    ll sum_sq = 0;
    for (int v = 1; v < sz; ++v) {
        int diff = sam.st[v].len - sam.st[sam.st[v].link].len;
        ll c = occ[v];
        sum_sq += (ll)diff * c * c;
    }

    ll total_substrings = (ll)n * (n + 1) / 2;
    ll ans = (sum_sq + total_substrings) / 2;
    cout << ans << '\n';

    return 0;
}
