import sys

def is_beautiful(s: str) -> bool:
    """Check if a number string is beautiful (only '0'/'1', at most one '1')."""
    ones = 0
    for ch in s:
        if ch == '1':
            ones += 1
            if ones > 1:
                return False
        elif ch != '0':
            return False
    return True

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    a = data[1:1 + n]

    # Any zero makes the whole product zero
    for s in a:
        if s == '0':
            print(0)
            return

    non_beautiful = None
    zero_count = 0

    for s in a:
        if is_beautiful(s):
            # beautiful numbers: 1 contributes 1 (no zeros), 10^k contributes k zeros
            if s != '1':
                zero_count += len(s) - 1   # "10...0" has len-1 zeros after the '1'
        else:
            # there should be at most one non-beautiful number
            non_beautiful = s

    # If all numbers were beautiful, the product is 10^zero_count
    if non_beautiful is None:
        non_beautiful = '1'

    # Result = non_beautiful * 10^zero_count
    result = non_beautiful + '0' * zero_count
    print(result)

if __name__ == "__main__":
    solve()
