    vector<vector<vector<uint64_t>>> bits(10, vector<vector<uint64_t>>(11, vector<uint64_t>(W, 0)));
    for (int idx=0; idx<V; idx++) {
        for (int c=0; c<10; c++) {
            int v = squares[idx][c];
            bits[c][v][idx>>6] |= 1ULL << (idx & 63);
        }
    }

    // full mask with all valid squares set
    vector<uint64_t> full(W, ~0ULL);
    if (V % 64) full[W-1] = (1ULL << (V % 64)) - 1;

    while (true) {
        array<int,10> a;
        for (int i=0; i<10; i++) cin >> a[i];
        if (all_of(a.begin(), a.end(), [](int x){return x==-1;})) break;

        // Check input consistency: no duplicate fixed values
        bool valid = true;
        vector<bool> used(11,false);
        for (int i=0; i<10; i++) {
            if (a[i] > 0) {
                if (a[i] < 1 || a[i] > 10 || used[a[i]]) {
                    valid = false;
                    break;
                }
                used[a[i]] = true;
            }
        }
        if (!valid) {
            cout << 0 << "\n";
            continue;
        }

        // If no fixed cells, answer = total valid squares
        int fixedCount = 0;
        for (int i=0; i<10; i++) if (a[i] > 0) fixedCount++;
        if (fixedCount == 0) {
            cout << V << "\n";
            continue;
        }

        // Intersect bitsets for fixed cells
        vector<uint64_t> cur = full;
        for (int i=0; i<10; i++) {
            if (a[i] > 0) {
                int v = a[i];
                for (int w=0; w<W; w++) {
                    cur[w] &= bits[i][v][w];
                }
            }
        }

        // Count set bits in intersection
        long long ans = 0;
        for (auto x : cur) ans += __builtin_popcountll(x);
        cout << ans << "\n";
    }

    return 0;
}
