import sys
import math
from collections import defaultdict

# ---------- Dinic max flow ----------
class Dinic:
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]

    def add_edge(self, u, v, cap):
        self.adj[u].append([v, cap, len(self.adj[v])])
        self.adj[v].append([u, 0, len(self.adj[u]) - 1])

    def bfs(self, s, t, level):
        for i in range(self.n):
            level[i] = -1
        q = [s]
        level[s] = 0
        for u in q:
            for v, cap, rev in self.adj[u]:
                if cap > 0 and level[v] < 0:
                    level[v] = level[u] + 1
                    q.append(v)
        return level[t] >= 0

    def dfs(self, u, t, f, level, it):
        if u == t:
            return f
        for i in range(it[u], len(self.adj[u])):
            it[u] = i
            v, cap, rev = self.adj[u][i]
            if cap > 0 and level[u] + 1 == level[v]:
                ret = self.dfs(v, t, min(f, cap), level, it)
                if ret > 0:
                    # decrease forward capacity
                    self.adj[u][i][1] -= ret
                    # increase reverse capacity
                    self.adj[v][rev][1] += ret
                    return ret
        return 0

    def max_flow(self, s, t):
        flow = 0
        INF = 10**18
        level = [-1] * self.n
        it = [0] * self.n
        while self.bfs(s, t, level):
            for i in range(self.n):
                it[i] = 0
            while True:
                pushed = self.dfs(s, t, INF, level, it)
                if pushed == 0:
                    break
                flow += pushed
        return flow


# ---------- Prime factorisation ----------
def sieve(limit):
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    primes = []
    for i in range(2, limit + 1):
        if is_prime[i]:
            primes.append(i)
            if i * i <= limit:
                step = i
                start = i * i
                is_prime[start:limit+1:step] = [False] * ((limit - start)//step + 1)
    return primes

PRIMES = sieve(31623)   # sqrt(1e9) ≈ 31623

def factorize(x):
    """return dict {prime: count} for x"""
    res = {}
    for p in PRIMES:
        if p * p > x:
            break
        if x % p == 0:
            cnt = 0
            while x % p == 0:
                x //= p
                cnt += 1
            res[p] = cnt
    if x > 1:
        res[x] = 1
    return res


# ---------- Main ----------
def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    a = [0] + [int(next(it)) for _ in range(n)]   # 1‑based

    # factorisation of each number
    factor = [None] * (n + 1)          # factor[i] = dict {prime: count}
    all_primes = set()
    for i in range(1, n + 1):
        if a[i] == 1:
            factor[i] = {}
        else:
            f = factorize(a[i])
            factor[i] = f
            for p in f:
                all_primes.add(p)

    # read edges
    edges = []
    for _ in range(m):
        i = int(next(it))
        j = int(next(it))
        edges.append((i, j))

    total_ops = 0
    INF = 10**9

    for p in all_primes:
        # build flow network
        # nodes: 0 = source, 1..n = indices, n+1 = sink
        S = 0
        T = n + 1
        dinic = Dinic(n + 2)

        # source -> odd indices
        for i in range(1, n + 1):
            cnt = factor[i].get(p, 0)
            if cnt == 0:
                continue
            if i % 2 == 1:          # odd -> left part
                dinic.add_edge(S, i, cnt)
            else:                    # even -> right part
                dinic.add_edge(i, T, cnt)

        # edges between parts
        for i, j in edges:
            # ensure direction from odd to even
            if i % 2 == 1 and j % 2 == 0:
                dinic.add_edge(i, j, INF)
            elif i % 2 == 0 and j % 2 == 1:
                dinic.add_edge(j, i, INF)
            # else: shouldn't happen because i+j odd guarantees parity difference

        total_ops += dinic.max_flow(S, T)

    print(total_ops)


if __name__ == "__main__":
