```python
import sys

def solve() -> None:
    s = sys.stdin.readline().strip()
    n = len(s)

    # dp[l][r] = minimal weight of substring s[l..r] (0-indexed, inclusive)
    dp = [[0] * n for _ in range(n)]

    for length in range(1, n + 1):
        for l in range(0, n - length + 1):
            r = l + length - 1

            # base: no compression
            best = length

            # try splitting the substring into two parts
            for m in range(l, r):
                cand = dp[l][m] + dp[m + 1][r]
                if cand < best:
                    best = cand

            # try representing the whole substring as a repetition
            for p in range(1, length):
                if length % p != 0:
                    continue
                # check whether s[l..r] consists of k copies of the first p characters
                pattern = s[l:l + p]
                ok = True
                for start in range(l, r + 1, p):
                    if s[start:start + p] != pattern:
                        ok = False
                        break
                if ok:
                    k = length // p
                    if k >= 2:
                        # weight of (pattern)^k is just the weight of the pattern
                        cand = dp[l][l + p - 1]
                        if cand < best:
                            best = cand

            dp[l][r] = best

    print(dp[0][n - 1])

if __name__ == "__main__":
    solve()
