class Solution:
    def isPatternPresent(self, P: str, S: str) -> int:
        # Check for start anchor '^'
        starts_with_caret = P.startswith('^')
        # Check for end anchor '$'
        ends_with_dollar = P.endswith('$')

        if starts_with_caret and ends_with_dollar:
            # Both anchors present: pattern must match both start and end
            pattern = P[1:-1]  # Remove both ^ and $
            if S.startswith(pattern) and S.endswith(pattern):
                return 1
            return 0
        elif starts_with_caret:
            # Only start anchor
            pattern = P[1:]  # Remove leading ^
            if S.startswith(pattern):
                return 1
            return 0
        elif ends_with_dollar:
            # Only end anchor
            pattern = P[:-1]  # Remove trailing $
            if S.endswith(pattern):
                return 1
            return 0
        else:
            # No anchors: check if P is a substring of S
            if P in S:
                return 1
            return 0
