MOD = 1000000007

# ---------- precompute primes up to 10000 ----------
MAX_VAL = 10000
is_prime = [True] * (MAX_VAL + 1)
is_prime[0] = is_prime[1] = False
primes = []
for i in range(2, MAX_VAL + 1):
    if is_prime[i]:
        primes.append(i)
        step = i
        start = i * i
        if start > MAX_VAL:
            continue
        for j in range(start, MAX_VAL + 1, step):
            is_prime[j] = False
