def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    T = int(next(it))
    out_lines = []
    for _ in range(T):
        n = int(next(it))
        # dictionary for max exponent of each prime
        max_exp = {}
        for _ in range(n):
            x = int(next(it))
            # factorize x
            temp = x
            for p in primes:
                if p * p > temp:
                    break
                if temp % p == 0:
                    cnt = 0
                    while temp % p == 0:
                        temp //= p
                        cnt += 1
                    if cnt > max_exp.get(p, 0):
                        max_exp[p] = cnt
            if temp > 1:
                # temp is a prime > MAX_VAL? Actually max is 10000, so temp <= 10000.
                # But after dividing by primes up to sqrt(temp), temp could be a prime > sqrt(original)
                # Since original <= 10000, temp <= 10000, so it's in our primes list but we didn't iterate to it.
                # We can just use temp as key.
                if 1 > max_exp.get(temp, 0):
                    max_exp[temp] = 1
        # compute result
        res = 1
        for p, e in max_exp.items():
            res = (res * pow(p, e, MOD)) % MOD
        out_lines.append(str(res))
    sys.stdout.write("\n".join(out_lines))

