```python
import sys

sys.setrecursionlimit(1 << 25)

INF = 10 ** 18


class SegTreeBeats:
    """segment tree supporting range chmin and point query"""

    def __init__(self, n, init_vals):
        self.n = n
        size = 1
        while size < n:
            size <<= 1
        self.size = size
        self.maxv = [0] * (2 * size)
        self.smax = [0] * (2 * size)
        self.cnt = [0] * (2 * size)
        self._build(1, 0, size - 1, init_vals)

    def _build(self, idx, l, r, vals):
        if l >= self.n:
            self.maxv[idx] = -INF
            self.smax[idx] = -INF
            self.cnt[idx] = 0
            return
        if l == r:
            v = vals[l] if l < self.n else -INF
            self.maxv[idx] = v
            self.smax[idx] = -INF
            self.cnt[idx] = 1
            return
        mid = (l + r) // 2
        self._build(idx * 2, l, mid, vals)
        self._build(idx * 2 + 1, mid + 1, r, vals)
        self._merge(idx)

    def _merge(self, idx):
        lc = idx * 2
        rc = idx * 2 + 1
        if self.maxv[lc] < self.maxv[rc]:
            self.maxv[idx] = self.maxv[rc]
            self.cnt[idx] = self.cnt[rc]
            self.smax[idx] = max(self.maxv[lc], self.smax[rc])
        elif self.maxv[lc] > self.maxv[rc]:
            self.maxv[idx] = self.maxv[lc]
            self.cnt[idx] = self.cnt[lc]
            self.smax[idx] = max(self.smax[lc], self.maxv[rc])
        else:
            self.maxv[idx] = self.maxv[lc]
            self.cnt[idx] = self.cnt[lc] + self.cnt[rc]
            self.smax[idx] = max(self.smax[lc], self.smax[rc])

    def _apply_chmin(self, idx, x):
        self.maxv[idx] = x

    def _push(self, idx):
        lc = idx * 2
        rc = idx * 2 + 1
        if self.maxv[idx] < self.maxv[lc]:
            self._apply_chmin(lc, self.maxv[idx])
        if self.maxv[idx] < self.maxv[rc]:
            self._apply_chmin(rc, self.maxv[idx])

    def range_chmin(self, ql, qr, x):
        if ql > qr:
            return
        self._range_chmin(1, 0, self.size - 1, ql, qr, x)

    def _range_chmin(self, idx, l, r, ql, qr, x):
        if r < ql or l > qr or self.maxv[idx] <= x:
            return
        if ql <= l and r <= qr and self.smax[idx] < x:
            self._apply_chmin(idx, x)
            return
        self._push(idx)
        mid = (l + r) // 2
        self._range_chmin(idx * 2, l, mid, ql, qr, x)
        self._range_chmin(idx * 2 + 1, mid + 1, r, ql, qr, x)
        self._merge(idx)

    def point_query(self, pos):
        return self._point_query(1, 0, self.size - 1, pos)

    def _point_query(self, idx, l, r, pos):
        if l == r:
            return self.maxv[idx]
        self._push(idx)
        mid = (l + r) // 2
        if pos <= mid:
            return self._point_query(idx * 2, l, mid, pos)
        else:
            return self._point_query(idx * 2 + 1, mid + 1, r, pos)


def solve() -> None:
    it = iter(sys.stdin.read().split())
    N = int(next(it))
    Q = int(next(it))

    initR = [N] * N
    initR[N - 1] = 1
    initC = [N] * N
    initC[N - 1] = 1

    segR = SegTreeBeats(N, initR)
    segC = SegTreeBeats(N, initC)

    black = (N - 2) * (N - 2)

    for _ in range(Q):
        typ = int(next(it))
        x = int(next(it))
        idx = x - 1

        if typ == 1:
            v = segC.point_query(idx)
            black -= v - 2
            segC.range_chmin(idx, idx, 1)
            if v > 2:
                segR.range_chmin(1, v - 2, x)
        else:
            v = segR.point_query(idx)
            black -= v - 2
            segR.range_chmin(idx, idx, 1)
            if v > 2:
                segC.range_chmin(1, v - 2, x)

    print(black)


if __name__ == "__main__":
    solve()
```

