import sys

MOD = 10**9 + 7
MAX_BIT = 20

def main():
    data = sys.stdin.buffer.read().split()
    it = iter(data)

    n = int(next(it))
    q = int(next(it))

    a = [0] * n
    for i in range(n):
        a[i] = int(next(it))

    queries = []
    for idx in range(q):
        l = int(next(it))
        x = int(next(it))
        queries.append((l, x, idx))

    # Precompute powers of 2
    pow2 = [1] * (n + 1)
    for i in range(1, n + 1):
        pow2[i] = (pow2[i - 1] * 2) % MOD

    # Linear basis
    basis = [0] * MAX_BIT
    rank = 0

    def insert(x):
        for b in range(MAX_BIT - 1, -1, -1):
            if (x >> b) & 1:
                if basis[b] == 0:
                    basis[b] = x
                    return True
                x ^= basis[b]
        return False

    def can(x):
        for b in range(MAX_BIT - 1, -1, -1):
            if (x >> b) & 1:
                if basis[b] == 0:
                    return False
                x ^= basis[b]
        return x == 0

    queries.sort(key=lambda t: t[0])

    ans = [0] * q
    cur = 0  # number of elements already inserted

    for l, x, idx in queries:
        while cur < l:
            if insert(a[cur]):
                rank += 1
            cur += 1

        if can(x):
            ans[idx] = pow2[l - rank]
        else:
            ans[idx] = 0

    sys.stdout.write("\n".join(map(str, ans)))

if __name__ == "__main__":
    main()
